from pathlib import Path
import sys
root=Path(sys.argv[1]).resolve()
p=root/"index.html"
s=p.read_text(encoding="utf-8").replace('lang="en"','lang="pt-BR"').replace('width=device-width, user-scalable=no, initial-scale=1.0','width=device-width, initial-scale=1.0, viewport-fit=cover')
s=s.replace('Your browser does not support the canvas tag.','Seu navegador não suporta o jogo.').replace('Your browser does not support JavaScript.','Ative JavaScript para jogar.')
s=s.replace('<script src="index.js"></script>', '<script src="mobile.js"></script>\n<script src="index.js"></script>')
s=s.replace('<script src="mobile.js"></script>', '''<script>
const paradoxoFetch=window.fetch.bind(window);
window.fetch=function(input,options){
 const resource=new URL(typeof input==='string'?input:input.url,location.href);
 if(resource.origin===location.origin&&resource.pathname.endsWith('/index.pck')){
  resource.searchParams.set('v','2.15.0');
  return paradoxoFetch(resource.href,options);
 }
 return paradoxoFetch(input,options);
};
</script>
<script src="mobile.js"></script>''')
s=s.replace('P.A.RADOXO — O Museu Fora do Tempo','P.A.RADOXO | O Museu Fora do Tempo')
s=s.replace('</head>','<meta name="application-version" content="2.15.0">\n</head>')
s=s.replace('</head>','<link rel="stylesheet" href="mobile.css">\n</head>')
s=s.replace('<canvas id="canvas">', '<section id="welcome" aria-labelledby="welcomeTitle"><div><p class="eyebrow">UMA AVENTURA DE RESTAURAÇÃO</p><h1 id="welcomeTitle">P.A.RADOXO</h1><h2>O Museu Fora do Tempo</h2><p>Restaure 12 obras, descubra padrões e devolva vida às histórias.</p><button id="enterMuseum">Entrar no museu</button><p class="small">No celular, jogue na horizontal. Toque para caminhar e use os botões da tela. Suas jornadas ficam salvas neste navegador.</p></div></section><section id="rotate" role="status"><div><div class="phoneIcon" aria-hidden="true">↻</div><h2>Gire o celular</h2><p>O museu foi preparado para jogar na horizontal.</p><p class="small">Se necessário, habilite a rotação automática do aparelho.</p></div></section><dialog id="nameDialog"><form id="nameForm"><h2>Como podemos chamar você?</h2><label for="mobileName">Seu nome ou apelido</label><input id="mobileName" type="text" autocomplete="off" autocapitalize="words" enterkeyhint="done"><p class="small">Até 20 caracteres. Acentos e emojis são aceitos.</p><div class="actions"><button id="cancelName" type="button">Voltar</button><button type="submit">Usar este nome</button></div></form></dialog><canvas id="canvas">')
s=s.replace("engine.startGame({", "window.paradoxo.start = () => engine.startGame({")
s=s.replace("setStatusMode('progress');", "setStatusMode('progress');\n        statusOverlay.style.visibility='hidden';")
s=s.replace("setStatusMode('hidden');", "setStatusMode('hidden');\n            window.paradoxo.ready=true;")
s=s.replace("}, displayFailureNotice);", "}, displayFailureNotice);\n        document.getElementById('enterMuseum').addEventListener('click', () => window.paradoxo.launch());")
p.write_text(s,encoding="utf-8")
(root/'mobile.css').write_text("""html,body{width:100%;height:100%;height:100dvh;background:#101d2c;color:#f5efe0;font-family:system-ui,sans-serif}body{overscroll-behavior:none}#canvas{width:100%;height:100%;touch-action:none}#welcome,#rotate{position:fixed;inset:0;z-index:10;display:grid;place-items:center;padding:max(16px,env(safe-area-inset-top)) max(24px,env(safe-area-inset-right));box-sizing:border-box;background:radial-gradient(ellipse at 70% 25%,#26434e,#101d2c 65%)}#welcome>div{max-width:700px;text-align:center}h1{font-size:clamp(38px,7vw,74px);color:#e9c78b;letter-spacing:.04em;margin:8px 0}h2{font-size:clamp(22px,3vw,32px);margin:12px 0}p{line-height:1.55;font-size:clamp(17px,2.2vw,22px)}.eyebrow{color:#8adbc1;font-size:14px;letter-spacing:.08em}.small{font-size:15px;color:#b4c6ce;max-width:600px}button{font:600 19px system-ui;min-height:48px;border-radius:14px;border:1px solid #e9c78b;background:#e9c78b;color:#132b39;padding:12px 26px;cursor:pointer}button:focus-visible,input:focus-visible{outline:3px solid #8adbc1;outline-offset:3px}button:disabled{opacity:.6;cursor:wait}#rotate{display:none;z-index:30;text-align:center}.phoneIcon{font-size:70px;color:#e9c78b}#status{background:#101d2c!important;z-index:9;padding:20px;box-sizing:border-box}#status-notice{font:18px system-ui;color:#f5efe0;max-width:600px;text-align:center}#status-progress{width:min(70vw,480px);accent-color:#8adbc1}dialog{z-index:40;width:min(620px,90vw);box-sizing:border-box;border:1px solid #426071;border-radius:18px;padding:24px;background:#0c1b27;color:#f5efe0;max-height:95dvh;overflow-y:auto}dialog::backdrop{background:#02070de6}dialog form{display:grid;gap:12px}dialog h2{font-size:24px}dialog label{font-size:18px}dialog input{font:24px system-ui;background:#1d3849;color:#fff;border:1px solid #78909c;border-radius:10px;min-height:54px;padding:4px 12px;box-sizing:border-box;width:100%}.actions{display:flex;gap:14px;justify-content:space-between}.actions button{flex:1}.actions button:first-child{background:#1d3849;color:#f5efe0;border-color:#426071}@media(pointer:coarse) and (orientation:portrait){#rotate{display:grid}}@media(max-height:430px){#welcome h1{font-size:40px}#welcome h2{font-size:22px}#welcome p{margin:8px 0;font-size:16px}#welcome .small{font-size:13px}dialog{padding:14px 22px}dialog h2{margin:0}dialog form{gap:8px}dialog .small{margin:0}}""",encoding="utf-8")
(root/'mobile.js').write_text("""(()=>{let pending=null;const dialog=document.getElementById('nameDialog');const input=document.getElementById('mobileName');let started=false;const coarse=matchMedia('(pointer:coarse)').matches||navigator.maxTouchPoints>0;window.paradoxo={ready:false,start:null,takeName(){const result=pending;pending=null;return result},openName(value){if(dialog.open)return;input.value=value;dialog.showModal();input.focus()},launch(){if(started||!this.start)return;started=true;const button=document.getElementById('enterMuseum');button.disabled=true;document.getElementById('welcome').style.display='none';document.getElementById('status').style.visibility='visible';if(coarse){const request=document.documentElement.requestFullscreen;if(request)request.call(document.documentElement).then(()=>screen.orientation?.lock?.('landscape')).catch(()=>{})}Promise.resolve(this.start()).catch(()=>{})}};document.getElementById('nameForm').addEventListener('submit',event=>{event.preventDefault();pending=input.value;dialog.close();document.getElementById('canvas').focus()});document.getElementById('cancelName').addEventListener('click',()=>{dialog.close();document.getElementById('canvas').focus()});const orientation=()=>{window.paradoxo.portrait=coarse&&innerHeight>innerWidth};addEventListener('resize',orientation);orientation();document.addEventListener('visibilitychange',()=>{if(document.hidden&&dialog.open)input.blur()});})();""",encoding="utf-8")
print('Mobile shell ready: landscape guidance, native name input and gesture startup.')
